const http = require('http');
const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');

const PORT = 8899;
const OUTPUT_DIR = '/app/output';
const VENDOR_DIR = '/app/vendor';

const MIME = {
  '.html': 'text/html',
  '.js': 'application/javascript',
  '.css': 'text/css',
  '.png': 'image/png',
  '.svg': 'image/svg+xml',
  '.json': 'application/json',
};

const server = http.createServer((req, res) => {
  let filePath;
  if (req.url === '/' || req.url === '/poster.html') {
    filePath = path.join(OUTPUT_DIR, 'poster.html');
  } else if (req.url.startsWith('/vendor/')) {
    filePath = path.join(VENDOR_DIR, req.url.replace('/vendor/', ''));
  } else {
    filePath = path.join(OUTPUT_DIR, req.url);
  }
  const ext = path.extname(filePath);
  res.setHeader('Content-Type', MIME[ext] || 'text/plain');
  try {
    res.end(fs.readFileSync(filePath));
  } catch {
    res.statusCode = 404;
    res.end('Not Found');
  }
});

async function main() {
  await new Promise(resolve => server.listen(PORT, resolve));
  console.log(`Server running on http://localhost:${PORT}`);

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  await page.setViewportSize({ width: 900, height: 1600 });
  await page.goto(`http://localhost:${PORT}/poster.html`, { waitUntil: 'networkidle' });

  // Wait for infographic rendering to complete
  await page.waitForTimeout(3000);

  // Get the poster element and its actual height
  const poster = await page.locator('.poster');
  const box = await poster.boundingBox();

  if (!box) {
    console.error('Poster element not found');
    process.exit(1);
  }

  console.log(`Poster dimensions: ${box.width}x${box.height}`);

  // Screenshot just the poster element at 2x DPR for crisp output
  await poster.screenshot({
    path: path.join(OUTPUT_DIR, 'final_poster.png'),
    omitBackground: false,
    scale: 'device',
  });

  console.log('Poster saved to /app/output/final_poster.png');
  await browser.close();
  server.close();
  process.exit(0);
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

