const http = require('http');
const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');

const PORT = 8899;
const OUTPUT_DIR = '/app/output';
const VENDOR_DIR = '/app/vendor';

const MIME = {
  '.html': 'text/html',
  '.js': 'application/javascript',
  '.css': 'text/css',
  '.png': 'image/png',
  '.svg': 'image/svg+xml',
  '.json': 'application/json',
};

const server = http.createServer((req, res) => {
  let filePath;
  if (req.url === '/' || req.url === '/poster.html') {
    filePath = path.join(OUTPUT_DIR, 'poster.html');
  } else if (req.url.startsWith('/vendor/')) {
    filePath = path.join(VENDOR_DIR, req.url.replace('/vendor/', ''));
  } else {
    filePath = path.join(OUTPUT_DIR, req.url);
  }
  const ext = path.extname(filePath);
  res.setHeader('Content-Type', MIME[ext] || 'text/plain');
  try {
    res.end(fs.readFileSync(filePath));
  } catch {
    res.statusCode = 404;
    res.end('Not Found');
  }
});

async function main() {
  await new Promise(resolve => server.listen(PORT, resolve));
  console.log(`Server running on http://localhost:${PORT}`);

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  // Capture console messages for debugging
  page.on('console', msg => {
    console.log(`[BROWSER:${msg.type()}] ${msg.text()}`);
  });
  page.on('pageerror', err => console.error(`[BROWSER ERROR] ${err.message}`));

  await page.setViewportSize({ width: 900, height: 1800 });
  await page.goto(`http://localhost:${PORT}/poster.html`, { waitUntil: 'networkidle', timeout: 15000 });

  // Wait for SVG elements to appear in infographic containers
  try {
    await page.waitForSelector('#leaderboard svg', { timeout: 8000 });
    console.log('Leaderboard SVG found');
  } catch (e) {
    console.error('Leaderboard SVG NOT found:', e.message);
  }

  try {
    await page.waitForSelector('#cost-compare svg', { timeout: 8000 });
    console.log('Cost-compare SVG found');
  } catch (e) {
    console.error('Cost-compare SVG NOT found:', e.message);
  }

  try {
    await page.waitForSelector('#takeaways svg', { timeout: 8000 });
    console.log('Takeaways SVG found');
  } catch (e) {
    console.error('Takeaways SVG NOT found:', e.message);
  }

  // Extra wait for rendering to stabilize
  await page.waitForTimeout(2000);

  // Check SVG counts
  const svgCount = await page.locator('svg').count();
  console.log(`Total SVGs on page: ${svgCount}`);

  // Get the poster element
  const poster = page.locator('.poster');
  const box = await poster.boundingBox();

  if (!box) {
    console.error('Poster element not found');
    process.exit(1);
  }

  console.log(`Poster dimensions: ${Math.round(box.width)}x${Math.round(box.height)}`);

  // Take screenshot of poster at 2x scale for crisp output
  await poster.screenshot({
    path: path.join(OUTPUT_DIR, 'final_poster.png'),
    omitBackground: false,
  });

  console.log('Poster saved to /app/output/final_poster.png');
  await browser.close();
  server.close();
  process.exit(0);
}

main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});

