  '.html': 'text/html',
  '.js': 'application/javascript',
  '.css': 'text/css',
  '.png': 'image/png',
  '.svg': 'image/svg+xml',
  '.json': 'application/json',
};

const server = http.createServer((req, res) => {
  let filePath;
  if (req.url === '/' || req.url === '/poster.html') {
    filePath = path.join(OUTPUT_DIR, 'poster.html');
  } else if (req.url.startsWith('/vendor/')) {
    filePath = path.join(VENDOR_DIR, req.url.replace('/vendor/', ''));
  } else {
    filePath = path.join(OUTPUT_DIR, req.url);
  }
  const ext = path.extname(filePath);
  res.setHeader('Content-Type', MIME[ext] || 'text/plain');
  try {
    res.end(fs.readFileSync(filePath));
  } catch {
    res.statusCode = 404;
    res.end('Not Found');
  }
});

async function main() {
  await new Promise(resolve => server.listen(PORT, resolve));
  console.log(`Server running on http://localhost:${PORT}`);

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  // Capture console messages for debugging
  page.on('console', msg => {
    console.log(`[BROWSER:${msg.type()}] ${msg.text()}`);
  });
  page.on('pageerror', err => console.error(`[BROWSER ERROR] ${err.message}`));

  await page.setViewportSize({ width: 900, height: 1800 });
  await page.goto(`http://localhost:${PORT}/poster.html`, { waitUntil: 'networkidle', timeout: 15000 });

  // Wait for SVG elements to appear in infographic containers
  try {
    await page.waitForSelector('#leaderboard svg', { timeout: 8000 });
    console.log('Leaderboard SVG found');
  } catch (e) {
    console.error('Leaderboard SVG NOT found:', e.message);
  }

  try {
