node -e "
const { chromium } = require('playwright');
const http = require('http');
const fs = require('fs');

(async () => {
  const server = http.createServer((req, res) => {
    let fp;
    if (req.url === '/' || req.url === '/poster.html') fp = '/app/output/poster.html';
    else if (req.url.startsWith('/vendor/')) fp = '/app/vendor/' + req.url.replace('/vendor/', '');
    else fp = '/app' + req.url;
    const ext = fp.split('.').pop();
    const mime = { html: 'text/html', js: 'application/javascript', css: 'text/css', svg: 'image/svg+xml' };
    res.setHeader('Content-Type', mime[ext] || 'text/plain');
    try { res.end(fs.readFileSync(fp)); } catch { res.statusCode = 404; res.end('NF'); }
  });
  await new Promise(r => server.listen(8896, r));

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.goto('http://localhost:8896/poster.html', { waitUntil: 'networkidle', timeout: 15000 });
  await page.waitForTimeout(4000);

  // Check rendered text colors
  const txt = await page.evaluate(() => {
    const svgs = document.querySelectorAll('svg');
    const results = [];
    for (const svg of svgs) {
      const texts = svg.querySelectorAll('text');
      const samples = [];
      for (let i = 0; i < Math.min(5, texts.length); i++) {
        const t = texts[i];
        samples.push({
          content: t.textContent?.substring(0, 30),
          fill: t.getAttribute('fill') || 'default',
          computed: getComputedStyle(t).fill
        });
      }
      results.push({ textCount: texts.length, samples });
    }
    return results;
  });
  console.log(JSON.stringify(txt, null, 2));

  await browser.close();
  server.close();
})();
" 2>&1

arguments.command:
node -e "
const { chromium } = require('playwright');
const http = require('http');
const fs = require('fs');

(async () => {
  const server = http.createServer((req, res) => {
    let fp;
    if (req.url === '/' || req.url === '/poster.html') fp = '/app/output/poster.html';
    else if (req.url.startsWith('/vendor/')) fp = '/app/vendor/' + req.url.replace('/vendor/', '');
    else fp = '/app' + req.url;
    res.setHeader('Content-Type', req.url.endsWith('.js') ? 'application/javascript' : 'text/html');
    try { res.end(fs.readFileSync(fp)); } catch { res.statusCode = 404; res.end('NF'); }
  });
  await new Promise(r => server.listen(8895, r));

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.goto('http://localhost:8895/poster.html', { waitUntil: 'networkidle', timeout: 15000 });
  await page.waitForTimeout(4000);

  // Get full text content of each SVG
  const content = await page.evaluate(() => {
    const result = {};
    const containers = ['leaderboard', 'cost-compare', 'takeaways'];
    for (const id of containers) {
      const svg = document.querySelector('#' + id + ' svg');
      if (svg) {
        // Get ALL text, including in tspan
        const allText = svg.querySelectorAll('text, tspan');
        const texts = Array.from(allText).map(t => ({
          tag: t.tagName,
          content: t.textContent?.trim()?.substring(0, 50),
          fill: t.getAttribute('fill')
        })).filter(t => t.content && t.content.length > 0);
        result[id] = {
          total: allText.length,
          first20: texts.slice(0, 20),
          allContent: texts.map(t => t.content).join(' | ')
        };
      }
    }
    return result;
  });
  console.log(JSON.stringify(content, null, 2));

  await browser.close();
  server.close();
})();
" 2>&1

