<script>
// Build the leaderboard bars
const models = [
  { rank: 1,  name: "GPT-5 (high)",        score: 88.0, cost: 29.08, family: "openai" },
  { rank: 2,  name: "GPT-5 (medium)",      score: 86.7, cost: 17.69, family: "openai" },
  { rank: 3,  name: "Claude 4.0 Opus",     score: 85.3, cost: 22.14, family: "anthropic" },
  { rank: 4,  name: "Claude 4.0 Sonnet",   score: 84.0, cost: 9.47,  family: "anthropic" },
  { rank: 5,  name: "Gemini 2.5 Pro",      score: 82.7, cost: 4.92,  family: "google" },
  { rank: 6,  name: "o3 (high)",           score: 82.2, cost: 18.35, family: "oseries" },
  { rank: 7,  name: "GPT-5 (low)",         score: 81.3, cost: 8.12,  family: "openai" },
  { rank: 8,  name: "DeepSeek R1-0528",    score: 80.4, cost: 3.88,  family: "deepseek" },
  { rank: 9,  name: "Claude 3.7 Sonnet",   score: 79.6, cost: 7.81,  family: "anthropic" },
  { rank: 10, name: "o3 (medium)",         score: 78.7, cost: 10.22, family: "oseries" },
  { rank: 11, name: "Gemini 2.5 Flash",    score: 76.4, cost: 1.28,  family: "google" },
  { rank: 12, name: "GPT-4.1",            score: 74.7, cost: 5.60,  family: "openai" },
  { rank: 13, name: "DeepSeek V3-0324",   score: 72.9, cost: 1.95,  family: "deepseek" },
  { rank: 14, name: "Claude 3.5 Sonnet",   score: 72.0, cost: 6.33,  family: "anthropic" },
  { rank: 15, name: "o4-mini (high)",      score: 71.1, cost: 4.47,  family: "oseries" },
];

const maxScore = 88.0;
const lbDiv = document.getElementById('leaderboard');

models.forEach(m => {
  const row = document.createElement('div');
  row.className = 'lb-row';

  const rank = document.createElement('span');
  rank.className = 'lb-rank' + (m.rank <= 3 ? ' top3' : '');
  rank.textContent = m.rank;

  const name = document.createElement('span');
  name.className = 'lb-name';
  name.textContent = m.name;

  const barBg = document.createElement('span');
  barBg.className = 'lb-bar-bg';
  const barFill = document.createElement('span');
  barFill.className = 'lb-bar-fill ' + m.family;
  barFill.style.width = (m.score / maxScore * 100) + '%';
  barBg.appendChild(barFill);

  const score = document.createElement('span');
  score.className = 'lb-score';
  score.textContent = m.score.toFixed(1) + '%';
  score.style.color = m.family === 'openai' ? '#10b981' :
                      m.family === 'anthropic' ? '#f59e0b' :
                      m.family === 'google' ? '#3b82f6' :
                      m.family === 'deepseek' ? '#8b5cf6' : '#06b6d4';

  const cost = document.createElement('span');
  cost.className = 'lb-cost';
  cost.textContent = '$' + m.cost.toFixed(2);

  row.appendChild(rank);
  row.appendChild(name);
  row.appendChild(barBg);
  row.appendChild(score);
  row.appendChild(cost);
  lbDiv.appendChild(row);
});
</script>
