const http = require('http');
const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');

const PORT = 8899;
const OUTPUT_DIR = '/app/output';

const MIME = {
  '.html': 'text/html',
  '.js': 'application/javascript',
  '.css': 'text/css',
  '.png': 'image/png',
};

const server = http.createServer((req, res) => {
  let filePath = path.join(OUTPUT_DIR, req.url === '/' ? 'poster.html' : req.url);
  const ext = path.extname(filePath);
  res.setHeader('Content-Type', MIME[ext] || 'text/plain');
  try {
    res.end(fs.readFileSync(filePath));
  } catch {
    res.statusCode = 404;
    res.end('Not Found');
  }
});

async function main() {
  await new Promise(resolve => server.listen(PORT, resolve));
  console.log(`Server on http://localhost:${PORT}`);

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  page.on('pageerror', err => console.error('[PAGE ERROR]', err.message));

  await page.setViewportSize({ width: 900, height: 100 });
  await page.goto(`http://localhost:${PORT}/poster.html`, { waitUntil: 'networkidle', timeout: 30000 });

  // Wait for fonts and JS rendering
  await page.waitForTimeout(1500);

  // Check if leaderboard bars rendered
  const barCount = await page.locator('.lb-bar-fill').count();
  console.log(`Leaderboard bars rendered: ${barCount}`);

  // Measure actual poster height
  const poster = page.locator('.poster');
  const box = await poster.boundingBox();
  if (!box) { console.error('Poster not found'); process.exit(1); }

  console.log(`Poster: ${Math.round(box.width)}x${Math.round(box.height)}`);

  // Set viewport to match poster height for clean capture
  await page.setViewportSize({
    width: Math.ceil(box.width) + 20,
    height: Math.ceil(box.height) + 20
  });

  // Screenshot just the poster
  await poster.screenshot({
    path: path.join(OUTPUT_DIR, 'final_poster.png'),
    omitBackground: false,
  });

  console.log('Saved /app/output/final_poster.png');
  await browser.close();
  server.close();
  process.exit(0);
}

main().catch(err => { console.error(err); process.exit(1); });

