node -e "
const { chromium } = require('playwright');
const http = require('http');
const fs = require('fs');
const path = require('path');

(async () => {
  const server = http.createServer((req, res) => {
    let fp = path.join('/app/output', req.url === '/' ? 'poster.html' : req.url);
    res.setHeader('Content-Type', 'text/html');
    try { res.end(fs.readFileSync(fp)); } catch { res.statusCode = 404; res.end('NF'); }
  });
  await new Promise(r => server.listen(8893, r));

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.goto('http://localhost:8893/poster.html', { waitUntil: 'networkidle', timeout: 15000 });
  await page.waitForTimeout(2000);

  // Quality checks
  const checks = await page.evaluate(() => {
    const r = {};
    r.leaderboardBars = document.querySelectorAll('.lb-bar-fill').length;
    r.heroCards = document.querySelectorAll('.hero-card').length;
    r.costCards = document.querySelectorAll('.cost-card').length;
    r.takeawayCards = document.querySelectorAll('.takeaway-card').length;
    r.title = document.querySelector('.poster-title')?.textContent?.trim()?.substring(0, 40);
    r.subtitle = !!document.querySelector('.poster-subtitle');

    // Check bar widths
    const bars = document.querySelectorAll('.lb-bar-fill');
    r.barWidths = Array.from(bars).map(b => b.style.width);

    return r;
  });
  console.log(JSON.stringify(checks, null, 2));

  await browser.close();
  server.close();
})();
" 2>&1

